UPDATE runic_inscriptions SET translation_sv = 'Denna sten lät husfru Rudvi göra över sin man, Jakob i Mannagården, som blev skjuten ihjäl med en bössosten från Visborg, då konung Erik var belägrad på nämnda slott. Och då hade lidit från Guds födelse fjorton hundra år och ett år mindre än femtio år. Vi bedja, att Gud vare nådig mot hans själ och alla kristna själar. Amen.'
WHERE signum = 'G 100' AND (translation_sv IS NULL OR translation_sv = '');
UPDATE runic_inscriptions SET translation_sv = 'Gairvald i Lye han lät göra detta gravvalv över sin son. Jakob i Rotarve … och Ragnvid de fick arv efter Gairvald i Lye.'
