UPDATE runic_inscriptions SET translation_sv = '§A Söte Herre Jesus Kristus, jag beder dig för din söta moders, fru Maria mös … och bedrövelse. §B <fuþ[o]rkhnia[s]> §C Hjälp Maria … §D … §E Hjälp Maria. §F … §G … §H <fuþork[hnia]stb[mlʀ]>'
