UPDATE runic_inscriptions SET translation_sv = '§A Ave Maria, gratia plena. Dominus tecum. Benedicta tu … §B Gloria Patri et Filio et Spir(itu) … §C … §D Jag är en arm, syndig människa … §E … §F I alla varen välkomna till (sam)tal … Denna kyrkan … <iaþis> Gud … §G Tyd runorna … §H … §I <fuþorkhniastbmlʀ> … runor(?) … §J … Jesus Nasarenus. … §K Maria … Sankta Maria. Mäster Jakob <fuþorkhnias>'
