UPDATE runic_inscriptions SET translation_sv = 'Jesus Krist vare Hallvis själ nådig! Unga-Gannes(?) husfru, Anga-Smeds dotter vilar här. Envar som ser härpå bedje Pater noster för Hallvis själ. Magister <gefs> gjorde mig. Botvid smed lät göra mig … vare oss nådig. Sigtjaud(?), hans husfru, som …'
