UPDATE runic_inscriptions SET translation_sv = '… gjorde denna kyrka, Hägmund med fyra ök och Liknvid med två ök och Hägvid med … Botvid med ett ök och Agnmund (och) Liknvid med ett ök och Fargair med två ök, Rolaik(?) med ett ök och Johan med två ök och Hägvid(?) med ett ök och Sigulv med två ök och Rodvald med ett ök och Ronvid med två ök och Hallvat med ett ök. Och allt det folk, som här haver arbete haft , både nämnt och onämnt, då misskunne dem Gud, både levande och döda.'
WHERE signum = 'G 119' AND (translation_sv IS NULL OR translation_sv = '');
UPDATE runic_inscriptions SET translation_sv = 'Peter lät göra denna sten över Botaid … <f> primstav … raden (?) … i tavlan. Bedjen böner …'
