UPDATE runic_inscriptions SET translation_sv = 'Sigmund lät resa stenen efter sina bröder och göra bro efter Sigbjärn - Sankt Mikael hjälpe hans själ - och efter Botraiv och efter Sigraiv och efter Aibjärn, fader till dem alla, och han bodde i byn (el. gården) längst söderut. Gairvid tecknade (eg. lade) ormslingorna … Sigmund har på så sätt åstadkommit vården. För män är det ett känt minnesmärke. Här skall stenen stå som märke, lysande på berget, bron invid den. Rodbjärn ristade dessa runor, några (dock) Gairlaiv, han känner dem väl.'
